/**
 * Quick-add: a DRAFT claim of an amount, dated the sheet's today with an empty note, for the person
 * of a name, matched as the person form matches names; a name not on the sheet adds the person first
 * with grade A. The whole of it is one change: a refused claim leaves no new person behind.
 */
@Service
public class QuickAddService {

    private static final String GRADE = "A";

    private final PersonRepository people;
    private final PersonService persons;
    private final ClaimService claims;

    public QuickAddService(PersonRepository people, PersonService persons, ClaimService claims) {
        this.people = people;
        this.persons = persons;
        this.claims = claims;
    }

    /** Returns the person the claim belongs to. */
    @Transactional
    public long add(String sheetId, String user, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = people.findBySheetIdAndNameIgnoreCase(sheetId, trimmed)
                .orElseGet(() -> persons.add(sheetId, user, trimmed, GRADE));
        return claims.add(sheetId, user, person.getId(), amount, null, "");
    }
}
package net.officefloor.hq.app.claim;

import java.util.Set;
import net.officefloor.hq.app.period.ClosedPeriodRefused;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/**
 * Opens a selection of claims together, numbered in list order: the people in the order they were
 * added, each person's newest claim first. Each claim is opened on its own, so one that cannot be
 * opened is refused and left as it is while the rest go through.
 */
@Service
public class BulkOpenService {

    public record Result(int opened, int refused) {
    }

    private final ClaimService claims;
    private final SelectedClaims selected;

    public BulkOpenService(ClaimService claims, SelectedClaims selected) {
        this.claims = claims;
        this.selected = selected;
    }

    public Result open(String sheetId, String user, Set<Long> claimIds) {
        int opened = 0;
        for (Claim c : selected.inListOrder(sheetId, claimIds)) {
            try {
                claims.move(sheetId, user, c.getId(), ClaimStatus.OPEN);
                opened++;
            } catch (ResponseStatusException | ClosedPeriodRefused refused) {
                // refused: left as it is
            }
        }
        return new Result(opened, claimIds.size() - opened);
    }
}
